<?php
// Read input
$line = trim(fgets(STDIN));
list($n, $sx, $sy, $dx, $dy, $t) = array_map('intval', explode(' ', $line));

// Function to compute (a mod n) that handles negative numbers correctly
function mod($a, $n) {
    return (($a % $n) + $n) % $n;
}

// Simulate the bear's movement for t seconds
for ($i = 0; $i < $t; $i++) {
    // Current cell
    $x = $sx;
    $y = $sy;

    // Number of raspberry bushes in current cell
    $k = $x + $y;

    // Update speed
    $dx += $k;
    $dy += $k;

    // Move to next cell
    $sx = mod($x + $dx - 1, $n) + 1;
    $sy = mod($y + $dy - 1, $n) + 1;
}

// Output final position
echo "$sx $sy\n";
?>
